(() => {
  const reels=document.querySelector('.reels'),status=document.querySelector('.status'),spin=document.querySelector('#spin'),reset=document.querySelector('#reset'),bet=document.querySelector('#bet');
  const colors=['#ff467b','#50e8ad','#69c8ff'];
  function art(symbol){if(symbol===0)return '<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 30 33 45 50 18 67 45 85 30 77 75H23Z" fill="#ffc65b" stroke="#fff0a0" stroke-width="3"/><path d="m30 60 20-15 20 15-20 10Z" fill="#a84ae9" stroke="#ffedb4" stroke-width="2"/><path d="M24 82h52" stroke="#ffe4a0" stroke-width="7"/></svg>';const color=colors[symbol-1];return `<svg viewBox="0 0 100 100" aria-hidden="true"><path d="m30 12 40 0 22 25 0 28-22 23H30L8 65V37Z" fill="${color}" stroke="#ffe2a0" stroke-width="4"/><path d="m30 12 8 26-30-1m62-25-8 26 30-1M8 65l30-7-8 30m62-23-30-7 8 30M38 38h24v20H38Z" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="2"/><path d="m30 12 8 26h24L70 12ZM8 37l30 1v20L8 65Z" fill="#fff" opacity=".23"/><path d="m38 58 24 0 8 30H30Z" fill="#14052c" opacity=".25"/></svg>`;}
  let balance=10000,busy=false,win=0;
  const money=n=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  function meters(){document.querySelector('#balance').textContent=money(balance);document.querySelector('#win').textContent=money(win);}
  function draw(values,winners=[]){reels.innerHTML=values.map((s,i)=>`<div class="symbol ${winners.includes(i)?'winner':''}" role="img" aria-label="${['Crown','Ruby','Emerald','Sapphire'][s]}">${art(s)}</div>`).join('');}
  const random=()=>{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296;};
  const lines=[[0,1,2],[3,4,5],[6,7,8],[0,4,8],[2,4,6]];
  spin.addEventListener('click',async()=>{if(busy)return;const amount=Number(bet.value);if(balance<amount){status.textContent='Preview balance is low. Reset credits to play again.';return;}busy=true;spin.disabled=reset.disabled=bet.disabled=true;balance-=amount;win=0;meters();status.textContent='Finding your fortune…';const result=Array.from({length:9},()=>Math.floor(random()*4)),multIndex=Math.floor(random()*3),mult=[5,10,15][multIndex];reels.classList.add('spinning');const timer=setInterval(()=>draw(Array.from({length:9},()=>Math.floor(random()*4))),85);await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?100:950));clearInterval(timer);reels.classList.remove('spinning');const winners=[];for(const line of lines){if(line.every(i=>result[i]===result[line[0]])){win+=amount*[12,6,4,3][result[line[0]]]*mult;winners.push(...line);}}balance+=win;draw(result,winners);document.querySelectorAll('.multiplier').forEach((el,i)=>el.classList.toggle('active',i===multIndex));meters();status.textContent=win?`Treasure found! ${money(win)} preview credits won.`:'No matching line. Try another spin.';busy=false;spin.disabled=reset.disabled=bet.disabled=false;});
  reset.addEventListener('click',()=>{if(busy)return;balance=10000;win=0;meters();status.textContent='Preview credits reset. Good luck!';});
  draw([0,1,2,0,1,2,0,1,2]);meters();
})();
